#!/bin/sh
# wp5 QA matrix — commands as executed on 2026-09-02 (cwd = devlog/_plan/260902_popup_font_stabilize). Server :4173 serves .pages (run npm run pages:stage first).

# 묶음 1: M1-M12 + R1
timeout 240 aside repl "const pages = { color: '.color-card', typography: '.typo-card', layout: '.layout-card', motion: '.motion-card' }; const modal=[]; const mobile=[]; for (const pg of Object.keys(pages)) { const p = await openTab('http://127.0.0.1:4173/'+pg+'.html?v='+Date.now()); await new Promise(r=>setTimeout(r,2000)); const errs=[]; p.on('console', m => { if (m.type && m.type()==='error') errs.push(String(m.text && m.text())); }); const step = async (how) => { await p.click(pages[pg]); await new Promise(r=>setTimeout(r,500)); const opened = await p.evaluate(() => ({ active: !!document.querySelector('.modal-overlay.active'), mainInert: document.querySelector('main').hasAttribute('inert'), overlayInert: !!document.querySelector('.modal-overlay').closest('[inert]'), focusInDialog: !!document.activeElement.closest('.modal-overlay') })); if (how==='button') await p.click('.modal-overlay.active .modal-close').catch(e=>'x'); if (how==='backdrop') await p.mouse.click(4,4); if (how==='escape') await p.keyboard.press('Escape'); await new Promise(r=>setTimeout(r,500)); const after = await p.evaluate((sel) => ({ closed: !document.querySelector('.modal-overlay.active'), mainInert: document.querySelector('main').hasAttribute('inert'), focusOnTrigger: !!document.activeElement.closest(sel), overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth, innerW: window.innerWidth }), pages[pg]); if (!after.closed) { await p.keyboard.press('Escape'); await new Promise(r=>setTimeout(r,300)); } return { how, opened, after }; }; modal.push({ page: pg, results: [await step('button'), await step('backdrop'), await step('escape')], consoleErrors: errs }); await p._sendToTarget('Emulation.setDeviceMetricsOverride', {width:390, height:844, deviceScaleFactor:2, mobile:true}); await new Promise(r=>setTimeout(r,900)); const m = await step('button'); mobile.push({ page: pg, vw: 390, how: 'button', after: m.after }); await p.close(); } console.log('M=' + JSON.stringify({modal, mobile}));" 2>&1 | rg '^M=' | sed 's/^M=//' > evidence/wp5_modal.json

# 묶음 2: F1-F7 + M13 + M14
timeout 200 aside repl "const out = { fonts: [], regression: {} }; const sel = { index: ['.logo','.header-count'], effects: ['#effects-title','.effect-card-kicker'], faq: ['h1','code'], color: ['#catalog-title','.color-result-count'], typography: ['#catalog-title','.typo-result-count'], layout: ['#catalog-title','.layout-result-count'], motion: ['#catalog-title','.motion-result-count'] }; for (const pg of Object.keys(sel)) { const p = await openTab('http://127.0.0.1:4173/'+pg+'.html?v='+Date.now()); await new Promise(r=>setTimeout(r,2200)); out.fonts.push(await p.evaluate((list) => { const root = getComputedStyle(document.documentElement); const cs = s => { const el = document.querySelector(s); return el ? getComputedStyle(el).fontFamily : null; }; const n = s => (s||'').replace(/['\"\\s]/g,''); const t = { sans: root.getPropertyValue('--font-sans').trim(), display: root.getPropertyValue('--font-display').trim(), mono: root.getPropertyValue('--font-mono').trim() }; const b = getComputedStyle(document.body).fontFamily, d = cs(list[0]), m = cs(list[1]); return { page: location.pathname, tokens: t, body: b, display: d, mono: m, ok: n(b)===n(t.sans) && n(d)===n(t.display) && n(m)===n(t.mono) }; }, sel[pg])); await p.close(); } { const p = await openTab('http://127.0.0.1:4173/index.html?v='+Date.now()); await new Promise(r=>setTimeout(r,3500)); await p.click('.ism-card .ism-card-header'); for (let i=0;i<20;i++){ if (await p.evaluate(()=>!!document.querySelector('.modal-overlay.active'))) break; await new Promise(r=>setTimeout(r,200)); } const o = await p.evaluate(() => ({ active: !!document.querySelector('.modal-overlay.active'), mainInert: document.querySelector('main').hasAttribute('inert') })); await p.keyboard.press('Escape'); await new Promise(r=>setTimeout(r,500)); const a = await p.evaluate(() => ({ closed: !document.querySelector('.modal-overlay.active'), mainInert: document.querySelector('main').hasAttribute('inert') })); out.regression.indexEscape = { o, a }; await p.close(); } { const p = await openTab('http://127.0.0.1:4173/effects.html?v='+Date.now()); await new Promise(r=>setTimeout(r,3000)); await p.click('.effect-card'); await new Promise(r=>setTimeout(r,700)); const o = await p.evaluate(() => ({ active: !!document.querySelector('.modal-overlay.active'), mainInert: document.querySelector('main').hasAttribute('inert') })); await p.click('.modal-overlay.active .modal-close').catch(e=>'x'); await new Promise(r=>setTimeout(r,500)); const a = await p.evaluate(() => ({ closed: !document.querySelector('.modal-overlay.active'), mainInert: document.querySelector('main').hasAttribute('inert') })); out.regression.effectsButton = { o, a }; await p.close(); } console.log('Q=' + JSON.stringify(out));" 2>&1 | rg '^Q=' | sed 's/^Q=//' > evidence/wp5_fonts_regression.json

# 묶음 3: G1 (2판 — finder 번호는 dialog가 열린 상태에서, visible 조건 포함해 측정)
timeout 240 aside repl "const geometry = []; for (const pg of ['index','effects']) { for (const vw of [1440,390]) { const p = await openTab('http://127.0.0.1:4173/'+pg+'.html?v='+Date.now()); await p._sendToTarget('Emulation.setDeviceMetricsOverride', {width:vw, height:900, deviceScaleFactor:1, mobile: vw<800}); await new Promise(r=>setTimeout(r,3200)); let finder = null; if (pg==='index') { await p.click('#finder-trigger'); await new Promise(r=>setTimeout(r,800)); await p.evaluate(() => { for (const name of ['project','mood','brightness']) { const radio = document.querySelector('input.finder-radio[name=\\"'+name+'\\"]'); if (radio) { radio.checked = true; radio.dispatchEvent(new Event('change', {bubbles:true})); } } }); await new Promise(r=>setTimeout(r,400)); await p.evaluate(() => { const b = document.getElementById('finder-submit'); if (b && !b.disabled) b.click(); }); await new Promise(r=>setTimeout(r,900)); finder = await p.evaluate(() => { const d = document.getElementById('finder-dialog'); const cells = Array.from(document.querySelectorAll('.finder-result-num')).map(el => ({ sel: '.finder-result-num', sw: el.scrollWidth, cw: el.clientWidth, visible: el.getClientRects().length > 0, ok: el.getClientRects().length > 0 && el.scrollWidth <= el.clientWidth + 1 })); return { dialogOpen: !!(d && d.open), cells, allOk: cells.length > 0 && cells.every(c=>c.ok) }; }); await p.evaluate(() => { const d = document.getElementById('finder-dialog'); if (d && d.open) d.close(); }); await new Promise(r=>setTimeout(r,300)); await p.click('.ism-card .ism-card-header'); } else { await p.click('.effect-card'); } await new Promise(r=>setTimeout(r,1200)); const modal = await p.evaluate(([pg, vw]) => { const de = document.documentElement; const clip = s => Array.from(document.querySelectorAll(s)).slice(0,6).map(el => ({ sel: s, sw: el.scrollWidth, cw: el.clientWidth, visible: el.getClientRects().length > 0, ok: el.getClientRects().length > 0 && el.scrollWidth <= el.clientWidth + 1 })); const cells = [...clip('.header-count'), ...clip('.export-tab'), ...clip('.export-title')]; return { page: pg, vw, innerW: window.innerWidth, modalOpen: !!document.querySelector('.modal-overlay.active'), exportTabs: document.querySelectorAll('.export-tab').length, pageOverflow: de.scrollWidth > de.clientWidth, cells, allOk: cells.length > 0 && cells.every(c=>c.ok) }; }, [pg, vw]); geometry.push({ ...modal, finder }); await p.keyboard.press('Escape'); await p.close(); } } console.log('G=' + JSON.stringify(geometry));" 2>&1 | rg '^G=' | sed 's/^G=//' > evidence/wp5_geometry.json

